import React, { useState, useEffect } from 'react';
import { throttle } from 'lodash'; // Import throttle from Lodash
import useMarvelApi from '../hooks/useMarvelApi';
import Comic from '../components/Comic';
import '../styles/searchPage.css';

function Search() {
  const [query, setQuery] = useState('');
  const { data, loading, error, hasMore, fetchData } = useMarvelApi(query);

  useEffect(() => {
    const handleScroll = () => {
      // Check if we're near the bottom of the page
      const nearBottom = window.innerHeight + document.documentElement.scrollTop >= document.documentElement.offsetHeight - 100; // 100px threshold
      if (nearBottom && !loading && hasMore) {
        fetchData();
      }
    };

    // Wrap handleScroll with throttle
    // This function will only be allowed to execute once every 200 milliseconds
    const throttledHandleScroll = throttle(handleScroll, 200);

    window.addEventListener('scroll', throttledHandleScroll);
    return () => window.removeEventListener('scroll', throttledHandleScroll);
  }, [loading, hasMore, fetchData]); // Make sure to include fetchData in your dependency array if it's stable or memoized

  return (
    <section id="search-section">
      <h1>Search Marvel Characters</h1>
      <input type="text" placeholder="Enter character name" value={query} onChange={(e) => setQuery(e.target.value)} />
      {loading && <div>Loading...</div>}
      {error && <div>Error: {error.message}</div>}
      <h2>Versions of Hero</h2>
      {data && <Comic characters={data} />}
    </section>
  );
}

export default Search;
